(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.013-t*0.18)*14;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.015+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.025+t*0.4)*8 + Math.cos((y+w1y)*0.02-t*0.35)*6;
  const w2y = Math.cos((y+w1y)*0.022-t*0.38)*7 + Math.sin((x+w1x)*0.019+t*0.42)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 75+Math.cos(t*0.35)*55, 0.075, 2.1, 0.0, 0.6],
    [320+Math.cos(t*0.45)*105, 165+Math.sin(t*0.65)*55, 0.095, 1.8, 1.2, 0.5],
    [240+Math.sin(t*0.28+2)*145, 115+Math.cos(t*0.48+1)*95, 0.058, 2.4, 2.5, 0.7],
    [110+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.55+3)*65, 0.11, 1.55, 3.8, 0.45],
    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 5.1, 0.55],
    [240+Math.cos(t*0.32+5)*125, 205+Math.sin(t*0.52)*85, 0.085, 1.95, 0.8, 0.65],
    [80+Math.sin(t*0.6+3)*70, 50+Math.cos(t*0.4+4)*60, 0.1, 2.2, 4.2, 0.5],
    [400+Math.cos(t*0.55+2)*80, 200+Math.sin(t*0.7+1)*70, 0.072, 2.5, 1.8, 0.6]
  ];
  let aS=0, iS=0, hS=0;
  for(const[sX,sY,f,sp,ph,am]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*f-t*sp+ph);
    const w2=Math.sin(d*f*0.6+t*sp*0.5+ph+2.0);
    const w3=Math.sin(d*f*1.3-t*sp*0.8+ph+4.0)*0.5;
    aS+=(w+w3)*am; iS+=(w2+w3*0.7)*am; hS+=Math.cos(d*f*0.8-t*sp*0.3+ph)*am;
  }
  const n=src.length, act=aS/n, inh=iS/n, hab=hS/n;
  const bg1=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2;
  const bg2=Math.sin((sx+sy)*0.11+t*2.2)*0.25+Math.sin((sx-sy)*0.095-t*1.8)*0.25;
  const bg3=Math.sin(sx*0.06+t*1.5)*Math.cos(sy*0.055-t*1.2)*0.15;
  const bg=bg1+bg2+bg3;
