  const sp3=Math.sin(dist*0.06-ang*2-t*2.0)*0.4;
  const spiral=(sp1+sp2+sp3)/2.2;
  const voronoi=()=>{
    let md=1e9,md2=1e9,ci=0;
    for(let i=0;i<12;i++){
      const vx=80+((i*137.508+t*18)%400), vy=30+((i*97.31+t*12)%180);
      const dx=sx-vx,dy=sy-vy,d=dx*dx+dy*dy;
      if(d<md){md2=md;md=d;ci=i;}else if(d<md2)md2=d;
    }
    return(Math.sqrt(md2)-Math.sqrt(md))*0.15+Math.sin(ci*2.1+t*0.5)*0.2;
  };
  const cell=voronoi();
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.28-t*2.5)*0.12;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral*0.4+cell*0.2+micro)*2.0);
  const hShift=hab*0.15+spiral*0.05;
  const detail=Math.sin(reaction*8)*0.04+Math.sin(sx*0.5)*Math.sin(sy*0.5)*0.02;
  const v=Math.max(0,Math.min(1,(reaction*0.5+0.5+hShift*0.1+detail)*1.0));
  const pal=[
    [5,12,55],[12,45,95],[18,85,125],[25,135,130],[60,170,120],
    [140,195,85],[210,195,60],[230,155,55],[220,100,60],[190,60,65],
    [140,35,70],[90,20,65],[45,15,60],[15,20,72],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,reaction)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*25)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*15)|0)
  ];
}
